/bin/zsh -lc "python3 -m py_compile pov.py && python3 - <<'PY'
from pov import Tree


def assert_tree(actual, expected):
    assert actual == expected, (actual.__dict__(), expected.__dict__())

# Singleton and identity/immutability.
tree = Tree(\"x\")
assert_tree(tree.from_pov(\"x\"), Tree(\"x\"))
assert tree.__dict__() == {\"x\": []}

# Parent with siblings.
tree = Tree(\"parent\", [Tree(\"a\"), Tree(\"x\"), Tree(\"b\"), Tree(\"c\")])
assert_tree(
    tree.from_pov(\"x\"),
    Tree(\"x\", [Tree(\"parent\", [Tree(\"a\"), Tree(\"b\"), Tree(\"c\")])]),
)
assert tree.path_to(\"x\", \"parent\") == [\"x\", \"parent\"]
assert tree.path_to(\"x\", \"b\") == [\"x\", \"parent\", \"b\"]
assert tree.__dict__() == {
    \"parent\": [{\"a\": []}, {\"b\": []}, {\"c\": []}, {\"x\": []}]
}

# New root's children stay attached.
tree = Tree(\"parent\", [Tree(\"x\", [Tree(\"kid-0\"), Tree(\"kid-1\")])])
assert_tree(
    tree.from_pov(\"x\"),
    Tree(\"x\", [Tree(\"kid-0\"), Tree(\"kid-1\"), Tree(\"parent\")]),
)

# Cousins and path joins.
tree = Tree(\"grandparent\", [
    Tree(\"parent\", [
        Tree(\"x\", [Tree(\"kid-0\"), Tree(\"kid-1\")]),
        Tree(\"sibling-0\"),
        Tree(\"sibling-1\"),
    ]),
    Tree(\"uncle\", [Tree(\"cousin-0\"), Tree(\"cousin-1\")]),
])
assert_tree(
    tree.from_pov(\"x\"),
    Tree(\"x\", [
        Tree(\"kid-0\"),
        Tree(\"kid-1\"),
        Tree(\"parent\", [
            Tree(\"sibling-0\"),
            Tree(\"sibling-1\"),
            Tree(\"grandparent\", [
                Tree(\"uncle\", [Tree(\"cousin-0\"), Tree(\"cousin-1\")])
            ]),
        ]),
    ]),
)
assert tree.path_to(\"x\", \"cousin-1\") == [
    \"x\", \"parent\", \"grandparent\", \"uncle\", \"cousin-1\"
]
assert tree.path_to(\"kid-0\", \"cousin-1\") == [
    \"kid-0\", \"x\", \"parent\", \"grandparent\", \"uncle\", \"cousin-1\"
]
assert tree.path_to(\"x\", \"x\") == [\"x\"]

for operation in (
    lambda: tree.from_pov(\"missing\"),
    lambda: tree.path_to(\"missing\", \"x\"),
    lambda: tree.path_to(\"x\", \"missing\"),
):
    try:
        operation()
    except ValueError as error:
        assert str(error) in {
            \"Tree could not be reoriented\",
            \"No path found\",
        }
    else:
        raise AssertionError(\"missing node did not raise\")

try:
    tree.from_pov(\"missing\")
except ValueError as error:
    assert str(error) == \"Tree could not be reoriented\"
try:
    tree.path_to(\"missing\", \"x\")
except ValueError as error:
    assert str(error) == \"No path found\"

print(\"local sanity checks passed\")
PY"

